func main() {
	// Create an external counter
	count := new(int)
	*count = 0

	destination := new(bool)

	// Test 1: Multiple invocations with external counter
	fmt.Println("Test 1: Multiple invocations with external counter")
	flag := &BoolWithInverseFlag{
		Name:        "env",
		Destination: destination,
		Config: BoolConfig{
			Count: count,
		},
	}

	cmd := &Command{
		Flags: []Flag{flag},
		Action: func(_ context.Context, _ *Command) error {
			return nil
		},
	}

	if err := cmd.Run(context.Background(), []string{"prog", "--env", "--env", "--env"}); err != nil {
		log.Fatalf("error: %v", err)
	}

	fmt.Printf("External counter value: %d\n", *count)
	fmt.Printf("flag.Count() value: %d\n", flag.Count())
	fmt.Printf("Destination value: %v\n", *destination)

	if *count != 3 || flag.Count() != 3 {
		log.Fatalf("FAILED: Expected count to be 3, got external=%d, Count()=%d", *count, flag.Count())
	}

	fmt.Println("✓ Test 1 passed!\n")

	// Test 2: OnlyOnce with external counter
	fmt.Println("Test 2: OnlyOnce with external counter (should error on duplicate)")
	count2 := new(int)
	*count2 = 0
	destination2 := new(bool)

	flag2 := &BoolWithInverseFlag{
		Name:        "verbose",
		Destination: destination2,
		OnlyOnce:    true,
		Config: BoolConfig{
			Count: count2,
		},
	}

	cmd2 := &Command{
		Flags: []Flag{flag2},
		Action: func(_ context.Context, _ *Command) error {
			return nil
		},
	}

	err := cmd2.Run(context.Background(), []string{"prog", "--verbose", "--verbose"})
	if err == nil {
		log.Fatalf("FAILED: Expected error on duplicate flag with OnlyOnce")
	}

	fmt.Printf("Got expected error: %v\n", err)
	fmt.Printf("External counter value after error: %d\n", *count2)

	if *count2 != 1 {
		log.Fatalf("FAILED: Expected count to be 1 after error, got %d", *count2)
	}

	fmt.Println("✓ Test 2 passed!")
}
