package cli

import (
	"context"
	"testing"
)

func TestBareDashParsing(t *testing.T) {
	tests := []struct {
		name        string
		args        []string
		wantPosArgs []string
		wantFlag    string
		wantErr     bool
	}{
		{
			name:        "bare dash with positional args",
			args:        []string{"cmd", "-", "foo", "bar"},
			wantPosArgs: []string{"-", "foo", "bar"},
		},
		{
			name:        "bare dash with flag after it",
			args:        []string{"cmd", "-", "--option", "value", "foo"},
			wantPosArgs: []string{"-", "foo"},
			wantFlag:    "value",
		},
		{
			name:        "bare dash with double dash terminator",
			args:        []string{"cmd", "-", "--", "foo", "--bar"},
			wantPosArgs: []string{"-", "foo", "--bar"},
		},
		{
			name:        "bare dash with undefined flag should error",
			args:        []string{"cmd", "-", "--undefined", "foo"},
			wantErr:     true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var gotArgs Args
			var gotFlag string
			cmd := &Command{
				Name: "cmd",
				Flags: []Flag{
					&StringFlag{
						Name: "option",
					},
				},
				Action: func(_ context.Context, cmd *Command) error {
					gotArgs = cmd.Args()
					gotFlag = cmd.String("option")
					return nil
				},
			}

			err := cmd.Run(context.Background(), tt.args)
			if tt.wantErr {
				if err == nil {
					t.Errorf("expected error, got nil")
				}
				return
			}
			if err != nil {
				t.Errorf("unexpected error: %v", err)
				return
			}

			if gotArgs == nil {
				t.Errorf("got nil args")
				return
			}

			gotSlice := gotArgs.Slice()
			if len(gotSlice) != len(tt.wantPosArgs) {
				t.Errorf("got %d positional args, want %d: %v vs %v", len(gotSlice), len(tt.wantPosArgs), gotSlice, tt.wantPosArgs)
				return
			}

			for i, want := range tt.wantPosArgs {
				if got := gotSlice[i]; got != want {
					t.Errorf("positional arg %d: got %q, want %q", i, got, want)
				}
			}

			if tt.wantFlag != "" && gotFlag != tt.wantFlag {
				t.Errorf("flag value: got %q, want %q", gotFlag, tt.wantFlag)
			}
		})
	}
}
