import { describe, test, expect, vi } from 'vitest';
import { baseParse as parse, transform, ErrorCodes, NodeTypes } from './packages/compiler-core/dist/compiler-core.cjs';
import { transformVBindShorthand } from './packages/compiler-core/dist/compiler-core.cjs';
import { transformBind } from './packages/compiler-core/dist/compiler-core.cjs';
import { transformElement } from './packages/compiler-core/dist/compiler-core.cjs';

function parseWithVBind(template, options = {}) {
  const ast = parse(template)
  transform(ast, {
    nodeTransforms: [
      transformVBindShorthand,
      transformElement,
    ],
    directiveTransforms: {
      bind: transformBind,
    },
    ...options,
  })
  return ast.children[0]
}

describe('v-bind shorthand issues', () => {
  test('invalid static argument like :2xl', () => {
    const onError = vi.fn()
    const node = parseWithVBind(`<div :2xl />`, { onError })
    console.log('Errors:', onError.mock.calls.length)
    onError.mock.calls.forEach((call, idx) => {
      console.log(`Error ${idx}:`, call[0].code, call[0].message)
    })
    expect(onError.mock.calls.length).toBeGreaterThan(0)
  })

  test('dynamic argument v-bind:[arg]', () => {
    const onError = vi.fn()
    const node = parseWithVBind(`<div v-bind:[arg] />`, { onError })
    console.log('Errors for dynamic arg:', onError.mock.calls.length)
    onError.mock.calls.forEach((call, idx) => {
      console.log(`Error ${idx}:`, call[0].code, call[0].message)
    })
    expect(onError.mock.calls.length).toBe(1)
  })
})
